CREATE TABLE IF NOT EXISTS input_versions(id TEXT PRIMARY KEY, kind TEXT NOT NULL, version TEXT NOT NULL, sha256 TEXT NOT NULL, loaded_at TEXT NOT NULL, content TEXT NOT NULL, UNIQUE(kind,sha256));
CREATE TABLE IF NOT EXISTS companies(id TEXT PRIMARY KEY,name TEXT NOT NULL,ats TEXT NOT NULL,board_token TEXT NOT NULL,active INTEGER NOT NULL DEFAULT 1,archetype_tags TEXT NOT NULL DEFAULT '[]',notes TEXT NOT NULL DEFAULT '');
CREATE TABLE IF NOT EXISTS ingest_runs(id TEXT PRIMARY KEY,started_at TEXT NOT NULL,finished_at TEXT,source TEXT NOT NULL,status TEXT NOT NULL,counts TEXT NOT NULL DEFAULT '{}',errors TEXT NOT NULL DEFAULT '[]');
CREATE TABLE IF NOT EXISTS raw_postings(id TEXT PRIMARY KEY,source TEXT NOT NULL,source_job_id TEXT,url TEXT,fetched_at TEXT NOT NULL,payload TEXT NOT NULL,payload_hash TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS jobs(id TEXT PRIMARY KEY,employer TEXT NOT NULL,title TEXT NOT NULL,normalized_title TEXT NOT NULL,location_text TEXT NOT NULL DEFAULT '',requisition_id TEXT,canonical_url TEXT,apply_url TEXT,posted_at TEXT,first_seen TEXT NOT NULL,last_seen TEXT NOT NULL,appearance_count INTEGER NOT NULL DEFAULT 1,listing_status TEXT NOT NULL DEFAULT 'unverified',is_agency INTEGER NOT NULL DEFAULT 0,fingerprint TEXT NOT NULL,aggregator_only INTEGER NOT NULL DEFAULT 0,description TEXT NOT NULL,posting_hash TEXT NOT NULL,official_verified INTEGER NOT NULL DEFAULT 0,features TEXT NOT NULL DEFAULT '[]',material_changes TEXT NOT NULL DEFAULT '[]',review_error TEXT);
CREATE INDEX IF NOT EXISTS jobs_employer ON jobs(employer);
CREATE INDEX IF NOT EXISTS jobs_fingerprint ON jobs(fingerprint);
CREATE TABLE IF NOT EXISTS job_sources(job_id TEXT NOT NULL REFERENCES jobs(id),source TEXT NOT NULL,url TEXT NOT NULL,first_seen TEXT NOT NULL,last_seen TEXT NOT NULL,PRIMARY KEY(job_id,source,url));
CREATE TABLE IF NOT EXISTS extractions(id TEXT PRIMARY KEY,job_id TEXT NOT NULL REFERENCES jobs(id),model TEXT NOT NULL,input_hash TEXT NOT NULL,structured TEXT NOT NULL,created_at TEXT NOT NULL);
CREATE INDEX IF NOT EXISTS extraction_hash ON extractions(input_hash);
CREATE TABLE IF NOT EXISTS filter_results(job_id TEXT PRIMARY KEY REFERENCES jobs(id),passed INTEGER NOT NULL,failed_rules TEXT NOT NULL,practical_eligibility TEXT NOT NULL,missing_fields TEXT NOT NULL,flags TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS triage_results(job_id TEXT PRIMARY KEY REFERENCES jobs(id),archetype TEXT NOT NULL,core_alignment_estimate REAL NOT NULL,keep INTEGER NOT NULL,reason TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS evaluations(id TEXT PRIMARY KEY,job_id TEXT NOT NULL REFERENCES jobs(id),bank_version TEXT NOT NULL,spec_version TEXT NOT NULL,bank_hash TEXT NOT NULL,spec_hash TEXT NOT NULL,posting_hash TEXT NOT NULL,model TEXT NOT NULL,anchors TEXT NOT NULL,computed TEXT NOT NULL,full_output TEXT NOT NULL,created_at TEXT NOT NULL,is_current INTEGER NOT NULL DEFAULT 1);
CREATE INDEX IF NOT EXISTS evaluations_current ON evaluations(job_id,is_current);
CREATE INDEX IF NOT EXISTS evaluations_latest ON evaluations(job_id,created_at DESC);
CREATE TABLE IF NOT EXISTS feedback(id TEXT PRIMARY KEY,job_id TEXT NOT NULL REFERENCES jobs(id),thumb TEXT NOT NULL,reason_tag TEXT NOT NULL,note TEXT NOT NULL,classification_at_time TEXT,features TEXT NOT NULL,created_at TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS preference_signal(feature TEXT PRIMARY KEY,weight REAL NOT NULL,updated_at TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS spec_change_proposals(id TEXT PRIMARY KEY,pattern TEXT NOT NULL UNIQUE,example_job_ids TEXT NOT NULL,proposed_change TEXT NOT NULL,status TEXT NOT NULL DEFAULT 'open',decided_at TEXT);
CREATE TABLE IF NOT EXISTS applications(id TEXT PRIMARY KEY,job_id TEXT NOT NULL UNIQUE REFERENCES jobs(id),status TEXT NOT NULL,status_history TEXT NOT NULL,applied_at TEXT,resume_document_id TEXT,cover_document_id TEXT,contacts TEXT NOT NULL DEFAULT '[]',notes TEXT NOT NULL DEFAULT '',follow_up_on TEXT);
CREATE TABLE IF NOT EXISTS documents(id TEXT PRIMARY KEY,job_id TEXT NOT NULL REFERENCES jobs(id),kind TEXT NOT NULL,version INTEGER NOT NULL,bank_version TEXT NOT NULL,spec_version TEXT NOT NULL,bank_hash TEXT NOT NULL,spec_hash TEXT NOT NULL,file_path TEXT,content TEXT NOT NULL,citations TEXT NOT NULL,verification_report TEXT NOT NULL,approved_by_user INTEGER NOT NULL DEFAULT 0,created_at TEXT NOT NULL,UNIQUE(job_id,kind,version));
CREATE TABLE IF NOT EXISTS bank_questions(id TEXT PRIMARY KEY,job_id TEXT REFERENCES jobs(id),question TEXT NOT NULL,answer TEXT,status TEXT NOT NULL DEFAULT 'open',created_at TEXT NOT NULL,draft TEXT);
CREATE TABLE IF NOT EXISTS llm_calls(id TEXT PRIMARY KEY,task TEXT NOT NULL,model TEXT NOT NULL,bank_version TEXT NOT NULL,spec_version TEXT NOT NULL,bank_hash TEXT NOT NULL,spec_hash TEXT NOT NULL,prompt TEXT NOT NULL,response TEXT,error TEXT,created_at TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS queue(id TEXT PRIMARY KEY,kind TEXT NOT NULL,payload TEXT NOT NULL,status TEXT NOT NULL DEFAULT 'pending',attempts INTEGER NOT NULL DEFAULT 0,run_after TEXT NOT NULL,locked_at TEXT,error TEXT,created_at TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS quality_checks(id TEXT PRIMARY KEY,job_id TEXT,kind TEXT NOT NULL,result TEXT NOT NULL,created_at TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS quality_reports(id TEXT PRIMARY KEY,period TEXT NOT NULL UNIQUE,content TEXT NOT NULL,created_at TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS decision_log(id TEXT PRIMARY KEY,proposal_id TEXT NOT NULL,decision TEXT NOT NULL,patch TEXT NOT NULL,created_at TEXT NOT NULL);
